/** 菜单点击回调 @see {@link https://script.deeke.cn/v2/floatWindow.html DeekeScript Pro 文档} */
type DeekeFloatWindowMenuHandler = (menuId?: string) => void;

/** deekeScript.json → floatWindow.menus[] / FloatWindow.setMenus @see {@link https://script.deeke.cn/v2/config.html DeekeScript Pro 文档} */
interface DeekeFloatWindowMenuItem {
    /** 菜单 id，给 FloatWindow.on / update 用 */
    id?: string;
    /** 内置 close / play / hide，或工程内图片路径 */
    icon?: string;
    /** 图标下方文案 */
    label?: string;
    /** 点击函数名，或内联 function（setMenus 时） */
    onTap?: string | DeekeFloatWindowMenuHandler;
    /** always（默认）/ running / idle */
    show?: "always" | "running" | "idle" | string;
    /** 圆形底色，如 #FFE8E6 */
    background?: string;
    /** 是否参与展示，默认 true */
    visible?: boolean;
}

/** FloatWindow.update 的 patch 参数 @see {@link https://script.deeke.cn/v2/floatWindow.html#floatwindow-updateid-patch DeekeScript Pro 文档} */
interface DeekeFloatWindowMenuPatch {
    icon?: string;
    label?: string;
    background?: string;
    show?: string;
    visible?: boolean;
    onTap?: string | DeekeFloatWindowMenuHandler;
}

/** deekeScript.json → floatWindow @see {@link https://script.deeke.cn/v2/config.html DeekeScript Pro 文档} */
interface DeekeFloatWindowConfig {
    /** 展开菜单项，最多 5 个；不写则连点两次停止任务 */
    menus?: DeekeFloatWindowMenuItem[];
}

/**
 * 项目悬浮窗展开菜单（点「运行」进入项目后，或打包 App）。未配置 floatWindow.menus 时与开发器一致：连点两次停止任务
 * @see {@link https://script.deeke.cn/v2/floatWindow.html DeekeScript Pro 文档}
 */
interface FloatWindow {
    /**
     * 运行时替换菜单。最多 5 个；传空数组表示运行时无菜单
     * @param {DeekeFloatWindowMenuItem[]} menus 菜单项数组
     * @see {@link https://script.deeke.cn/v2/floatWindow.html#floatwindow-setmenus DeekeScript Pro 文档}
     */
    setMenus(menus: DeekeFloatWindowMenuItem[]): void;
    /**
     * 绑定菜单项点击回调。传入对象可一次绑定多个 id → function
     * @param {Record<string, DeekeFloatWindowMenuHandler> | string} handlers 回调映射，或菜单 id
     * @param {DeekeFloatWindowMenuHandler} fn 单个 id 对应的回调（可选）（可选）
     * @see {@link https://script.deeke.cn/v2/floatWindow.html#floatwindow-on DeekeScript Pro 文档}
     */
    on(handlers: Record<string, DeekeFloatWindowMenuHandler> | string, fn?: DeekeFloatWindowMenuHandler): void;
    /**
     * 修改某个菜单项的 label / icon / background / show / visible 等，展开时会立刻刷新
     * @param {string} id 菜单 id
     * @param {DeekeFloatWindowMenuPatch} patch 要修改的字段
     * @see {@link https://script.deeke.cn/v2/floatWindow.html#floatwindow-update DeekeScript Pro 文档}
     */
    update(id: string, patch: DeekeFloatWindowMenuPatch): void;
    /**
     * 收起展开的扇形菜单
     * @see {@link https://script.deeke.cn/v2/floatWindow.html#floatwindow-collapse DeekeScript Pro 文档}
     */
    collapse(): void;
    /**
     * 从悬浮窗停止整项项目任务并恢复悬浮球 UI。菜单里手动停任务用本方法；Engines.closeAll() 在菜单回调线程无效
     * @see {@link https://script.deeke.cn/v2/floatWindow.html#floatwindow-stoptask DeekeScript Pro 文档}
     */
    stopTask(): void;
}
