    /**
     * 流式POST请求（支持Server-Sent Events等流式输出）
     * @param {string} url 请求URL
     * @param {object} json 请求体JSON对象
     * @param {(data: string) => void, onError: (error: string) => void} onData 数据回调函数，每收到一行数据时调用，参数为数据字符串
     * @see {@link https://script.deeke.cn/base/http/http.html#poststream-url-json-ondata DeekeScript Pro 文档}
     */
    postStream(url: string, json: object, onData: (data: string) => void, onError: (error: string) => void): void;
